export default async function install(app){
const layer=app.layers[app.config.layerId];app.assert(layer,'Parcel layer unavailable');app.view.popupEnabled=false;layer.popupEnabled=false;const lv=await app.view.whenLayerView(layer),sm=app.view.selectionManager;
const make=(tag,text)=>{const e=document.createElement(tag);if(text!=null)e.textContent=text;return e},style=(e,s)=>Object.assign(e.style,s);
const searchCard=make('section');style(searchCard,{position:'absolute',left:'14px',top:'14px',zIndex:'30',width:'min(350px, calc(100vw - 40px))',padding:'14px',borderRadius:'13px',background:'var(--calcite-color-foreground-1)',color:'var(--calcite-color-text-1)',boxShadow:'0 12px 34px rgba(20,36,52,.22)',border:'1px solid var(--calcite-color-border-1)',boxSizing:'border-box',pointerEvents:'auto'});
const title=make('div','PARCEL LOOKUP');style(title,{color:'var(--calcite-color-brand)',fontWeight:'700',letterSpacing:'.12em',fontSize:'.72rem',marginBottom:'9px'});const row=make('div');style(row,{display:'flex',gap:'8px'});const input=make('input');input.type='search';input.placeholder='Start typing an address or APN';input.setAttribute('aria-label','Search parcel address or APN');input.autocomplete='off';style(input,{minWidth:'0',flex:'1',padding:'10px',borderRadius:'8px',border:'1px solid var(--calcite-color-border-input)',background:'var(--calcite-color-foreground-1)',color:'var(--calcite-color-text-1)',font:'inherit'});const button=make('button','Search');button.type='button';style(button,{border:'0',borderRadius:'8px',padding:'0 13px',background:'var(--calcite-color-brand)',color:'white',font:'inherit',fontWeight:'600',cursor:'pointer'});row.append(input,button);const status=make('div','Type at least 3 characters for suggestions.');status.setAttribute('role','status');style(status,{marginTop:'8px',fontSize:'.83rem',color:'var(--calcite-color-text-2)'});const results=make('div');results.setAttribute('role','listbox');results.setAttribute('aria-label','Parcel suggestions');style(results,{display:'flex',flexDirection:'column',gap:'6px',marginTop:'8px',maxHeight:'240px',overflowY:'auto'});searchCard.append(title,row,status,results);
const infoCard=make('section');style(infoCard,{position:'absolute',right:'14px',top:'14px',zIndex:'31',width:'min(370px, calc(100vw - 40px))',maxHeight:'calc(100% - 28px)',overflowY:'auto',borderRadius:'14px',background:'var(--calcite-color-foreground-1)',color:'var(--calcite-color-text-1)',boxShadow:'0 14px 44px rgba(20,36,52,.24)',border:'1px solid var(--calcite-color-border-1)',boxSizing:'border-box',display:'none',pointerEvents:'auto'});app.view.ui.add(searchCard,'manual');app.view.ui.add(infoCard,'manual');
let revision=0,searchRevision=0,clickRevision=0,timer=null,highlight=null,highlightedId=null;const clearHighlight=()=>{highlight?.remove();highlight=null;highlightedId=null;infoCard.dataset.highlightActive='false'};const clearSelections=()=>{const ids=sm.getSelection(layer);if(ids?.length)sm.remove(layer,Array.from(ids))};const close=e=>{e?.stopPropagation();revision++;clickRevision++;clearHighlight();clearSelections();infoCard.style.display='none';infoCard.replaceChildren()};
const showInfo=a=>{const content=make('div');style(content,{padding:'18px',display:'flex',flexDirection:'column',gap:'12px'});const top=make('div');style(top,{display:'flex',justifyContent:'space-between',alignItems:'flex-start',gap:'12px'});const head=make('div'),k=make('div','PARCEL RECORD'),address=make('h2',String(a.prop_address||layer.title||'Selected parcel'));style(k,{color:'var(--calcite-color-brand)',fontSize:'.72rem',letterSpacing:'.12em',fontWeight:'700',marginBottom:'4px'});style(address,{margin:'0',fontSize:'1.12rem',lineHeight:'1.28',overflowWrap:'anywhere'});head.append(k,address);const x=make('button','×');x.type='button';x.setAttribute('aria-label','Close parcel details');style(x,{width:'34px',height:'34px',flex:'0 0 auto',border:'0',borderRadius:'50%',background:'var(--calcite-color-foreground-2)',color:'var(--calcite-color-text-1)',fontSize:'1.35rem',cursor:'pointer'});x.addEventListener('click',close);top.append(head,x);const badge=make('div','APN  '+String(a.apn??'—'));style(badge,{alignSelf:'flex-start',padding:'5px 10px',borderRadius:'999px',background:'var(--calcite-color-foreground-2)',fontSize:'.82rem',fontWeight:'600'});const grid=make('div');style(grid,{display:'grid',gridTemplateColumns:'1fr 1fr',gap:'9px'});const values=[['TOTAL VALUE',a.totalval==null?'—':'$'+Number(a.totalval).toLocaleString()],['BUILDING AREA',a.bldg_sqft==null?'—':Number(a.bldg_sqft).toLocaleString()+' sq ft'],['BUILDINGS',a.bldg_count??'—'],['FLOOD RISK',a.flood_risk??'—'],['WILDFIRE SCORE',a.wfir_risks==null?'—':Number(a.wfir_risks).toFixed(1)],['RIVERINE FLOOD',a.rfld_risks==null?'—':Number(a.rfld_risks).toFixed(1)]];for(const [label,value] of values){const cell=make('div');style(cell,{minWidth:'0',padding:'10px',borderRadius:'9px',background:'var(--calcite-color-foreground-2)'});const cap=make('div',label);style(cap,{fontSize:'.66rem',letterSpacing:'.08em',color:'var(--calcite-color-text-3)',fontWeight:'700',marginBottom:'5px'});const val=make('div',String(value));style(val,{fontSize:'.92rem',fontWeight:'600',overflowWrap:'anywhere'});cell.append(cap,val);grid.append(cell)}content.append(top,badge,grid);infoCard.replaceChildren(content);infoCard.style.display='block'};
const action=async({graphic})=>{const current=++revision,oid=graphic?.getObjectId();clearHighlight();clearSelections();if(oid==null)return;highlight=lv.highlight(oid);highlightedId=oid;infoCard.dataset.highlightActive='true';infoCard.style.display='block';infoCard.replaceChildren(make('p','Loading parcel details…'));try{const q=layer.createQuery();q.objectIds=[oid];q.outFields=['*'];q.returnGeometry=false;const {features}=await layer.queryFeatures(q);if(current!==revision)return;showInfo(features[0]?.attributes||{prop_address:'No parcel details found.'})}catch(e){if(current===revision)showInfo({prop_address:'Unable to load parcel details.'})}};
const onMapClick=async event=>{const target=event.native?.target;if(target&&(searchCard.contains(target)||infoCard.contains(target)))return;const request=++clickRevision;try{const hit=await app.view.hitTest({x:event.x,y:event.y},{include:[layer]});if(request!==clickRevision)return;const match=hit.results.find(r=>r.type==='graphic'&&r.graphic.layer===layer);if(match)await action({graphic:match.graphic})}catch(e){app.reportError(e)}};const clickHandle=app.view.on('click',onMapClick);
const search=async()=>{const term=input.value.trim(),request=++searchRevision;if(term.length<3){results.replaceChildren();status.textContent='Type at least 3 characters for suggestions.';return}status.textContent='Finding matching parcels…';results.replaceChildren();const safe=term.replace(/[\\%_]/g,c=>'\\'+c).replace(/'/g,"''");try{const q=layer.createQuery();q.where="apn LIKE '%"+safe+"%' OR prop_address LIKE '%"+safe+"%'";q.outFields=['OBJECTID','prop_address','apn'];q.returnGeometry=false;q.num=10;const {features}=await layer.queryFeatures(q);if(request!==searchRevision)return;if(!features.length){status.textContent='No matching parcels.';return}status.textContent='Suggestions · '+features.length+(features.length===10?'+':'')+' matches';for(const f of features){const b=make('button');b.type='button';b.setAttribute('role','option');style(b,{textAlign:'left',border:'1px solid var(--calcite-color-border-1)',borderRadius:'8px',padding:'8px 10px',background:'var(--calcite-color-foreground-1)',color:'var(--calcite-color-text-1)',font:'inherit',cursor:'pointer'});b.textContent=String(f.attributes.prop_address||'Parcel')+' · APN '+String(f.attributes.apn||'—');b.addEventListener('click',async()=>{const ticket=++clickRevision;status.textContent='Loading selected parcel…';const fq=layer.createQuery();fq.objectIds=[f.getObjectId()];fq.outFields=['*'];fq.returnGeometry=true;const {features:full}=await layer.queryFeatures(fq);if(ticket!==clickRevision||!full.length)return;input.value=String(full[0].attributes.prop_address||full[0].attributes.apn||'');results.replaceChildren();status.textContent='Parcel selected.';await action({graphic:full[0]});if(full[0].geometry)app.view.goTo(full[0].geometry).catch(()=>{})});results.append(b)}}catch(e){if(request===searchRevision)status.textContent='Search failed. Please try again.'}};
const onInput=()=>{clearTimeout(timer);timer=setTimeout(search,250)},onKey=e=>{if(e.key==='Enter'){clearTimeout(timer);search()}if(e.key==='Escape'){results.replaceChildren();status.textContent='Suggestions cleared.'}};input.addEventListener('input',onInput);input.addEventListener('keydown',onKey);button.addEventListener('click',search);app.actions.register('show-clicked-parcel',action);app.actions.register('inspect-parcel-card',()=>({cardVisible:infoCard.style.display!=='none',highlightActive:!!highlight,highlightedId}));app.onCleanup(()=>{revision++;clickRevision++;searchRevision++;clearTimeout(timer);clickHandle.remove();clearHighlight();clearSelections();input.removeEventListener('input',onInput);input.removeEventListener('keydown',onKey);button.removeEventListener('click',search);app.view.ui.remove(searchCard);app.view.ui.remove(infoCard)});return {installed:true,automaticRuntimeSelection:false,mapClickHitTest:true,singleHighlightOwner:true,closeCancelsPendingClicks:true,searchPreserved:true};
}